def error_report(log):
    tot, cnt, bad = {}, {}, {}
    for question, op, seconds, right in log:
        tot[op] = tot.get(op, 0) + seconds
        cnt[op] = cnt.get(op, 0) + 1
        bad[op] = bad.get(op, 0) + (not right)
    all_seconds = sum(tot.values())
    report = {op: (tot[op] / cnt[op], bad[op] / cnt[op], tot[op] / all_seconds) for op in tot}
    worst = max(report, key=lambda op: report[op][1])
    if report[worst][1] >= 0.25:
        drill = worst
    else:
        drill = max(report, key=lambda op: report[op][2])
    return report, drill
